const $ = (id) => document.getElementById(id);
const panel = $("letter");
const linesEl = $("lines");
const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

$("title").textContent = CONFIG.title;
$("sub").textContent = CONFIG.subtitle;


(function buildCode() {
  const a = $("code");
  const img = document.createElement("img");
  img.src = CONFIG.codeImg;
  img.alt = "Spotify code for the playlist";
  a.appendChild(img);
  if (CONFIG.playlistUrl) {
    a.href = CONFIG.playlistUrl;
    a.target = "_blank";
    a.rel = "noopener";
  }
})();


function setPhoto(src) {
  const c = $("cover");
  c.src = src;
  c.hidden = false;
  $("coverPh").hidden = true;
  $("bgImg").style.backgroundImage = 'url("' + src + '")';
  document.body.classList.add("has-photo");
}
if (CONFIG.photo) setPhoto(CONFIG.photo);
$("file").addEventListener("change", (e) => {
  const f = e.target.files && e.target.files[0];
  if (!f) return;
  const r = new FileReader();
  r.onload = () => setPhoto(r.result);
  r.readAsDataURL(f);
});


const items = [];
CONFIG.letter.forEach((text) => {
  if (!text) {
    const g = document.createElement("div");
    g.className = "gap";
    linesEl.appendChild(g);
    return;
  }
  const b = document.createElement("button");
  b.type = "button";
  b.className = "line";
  b.textContent = text;
  const idx = items.length;
  b.addEventListener("click", () => jump(idx));
  linesEl.appendChild(b);
  items.push(b);
});

const TOTAL = Math.max(150, items.length * 9);
const fmt = (s) => Math.floor(s / 60) + ":" + String(Math.floor(s % 60)).padStart(2, "0");
$("t1").textContent = fmt(TOTAL);

let active = 0;
let playing = false;
let repeat = false;
let timer = 0;

function pad() {
  const h = panel.clientHeight;
  linesEl.style.paddingTop = Math.round(h * 0.4) + "px";
  linesEl.style.paddingBottom = Math.round(h * 0.6) + "px";
}

function update() {
  const r = panel.getBoundingClientRect();
  const y = r.top + r.height * 0.4;
  let best = 0, bd = Infinity;
  items.forEach((el, i) => {
    const b = el.getBoundingClientRect();
    const d = Math.abs(b.top + b.height / 2 - y);
    if (d < bd) { bd = d; best = i; }
  });
  active = best;
  items.forEach((el, i) => {
    const d = Math.abs(i - best);
    el.style.setProperty("--d", d);
    el.classList.toggle("on", d === 0);
  });
  const frac = items.length > 1 ? best / (items.length - 1) : 0;
  $("fill").style.width = frac * 100 + "%";
  $("t0").textContent = fmt(frac * TOTAL);
  $("bar").setAttribute("aria-valuenow", Math.round(frac * 100));
}

let ticking = false;
panel.addEventListener("scroll", () => {
  if (ticking) return;
  ticking = true;
  requestAnimationFrame(() => { ticking = false; update(); });
}, { passive: true });

function goTo(i) {
  i = Math.max(0, Math.min(items.length - 1, i));
  const el = items[i];
  panel.scrollTo({
    top: el.offsetTop + el.offsetHeight / 2 - panel.clientHeight * 0.4,
    behavior: reduce ? "auto" : "smooth"
  });
}

function schedule() {
  clearTimeout(timer);
  if (!playing) return;
  const len = items[active] ? items[active].textContent.length : 20;
  timer = setTimeout(() => {
    if (active >= items.length - 1) {
      if (repeat) { goTo(0); schedule(); } else { setPlaying(false); }
      return;
    }
    goTo(active + 1);
    schedule();
  }, 1700 + len * 55);
}

function jump(i) { goTo(i); schedule(); }

function setPlaying(v) {
  playing = v;
  $("iconPlay").hidden = v;
  $("iconPause").hidden = !v;
  $("play").setAttribute("aria-label", v ? "Pause letter" : "Play letter");
  if (v && active >= items.length - 1) goTo(0);
  schedule();
}

$("play").href = CONFIG.playlistUrl || "#";
$("prev").addEventListener("click", () => jump(active - 1));
$("next").addEventListener("click", () => jump(active + 1));
$("repeat").addEventListener("click", (e) => {
  repeat = !repeat;
  e.currentTarget.setAttribute("aria-pressed", String(repeat));
});
$("heart").addEventListener("click", (e) => {
  const on = e.currentTarget.getAttribute("aria-pressed") !== "true";
  e.currentTarget.setAttribute("aria-pressed", String(on));
  e.currentTarget.setAttribute("aria-label", on ? "Unlike" : "Like");
});

const bar = $("bar");
bar.addEventListener("click", (e) => {
  const r = bar.getBoundingClientRect();
  const frac = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
  jump(Math.round(frac * (items.length - 1)));
});
bar.addEventListener("keydown", (e) => {
  if (e.key === "ArrowRight") { e.preventDefault(); jump(active + 1); }
  if (e.key === "ArrowLeft") { e.preventDefault(); jump(active - 1); }
});

window.addEventListener("resize", () => { pad(); update(); });
pad();
update();
